    size: number;
    label: string;
}) => (
    <div
        style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 8,
        }}
    >
        <img
            src={src}
            width={size}
            height={size}
            alt={label}
            style={{ border: '1px solid #e5e7eb', borderRadius: 16 }}
